const tabId = 343605414;
const details = await browserjs(tabId, () => {
  // Let's see how each daily card or item is structured
  const items = Array.from(document.querySelectorAll('.daily-list-item, .daily-forecast-card, a.daily-list-item'));
  return items.map(item => {
    // Check if there are child elements or siblings
    const date = item.querySelector('.date')?.innerText?.trim() || '';
    const temp = item.querySelector('.temp')?.innerText?.trim() || '';
    const precip = item.querySelector('.precip')?.innerText?.trim() || '';
    const phrase = item.querySelector('.phrase')?.innerText?.trim() || '';
    return { text: item.innerText.trim(), date, temp, precip, phrase };
  });
});
console.log(JSON.stringify(details, null, 2));

const tabId = 343605414;
const fullDailyData = await browserjs(tabId, () => {
  // Let's inspect the container that holds the daily forecast cards
  const container = document.querySelector('.page-column-1') || document.querySelector('.two-column-page-content');
  if (!container) return null;

  // AccuWeather daily forecast usually has daily-wrapper or card elements
  // Let's query all items with links or cards
  const cards = Array.from(container.querySelectorAll('.daily-forecast-card, .daily-wrapper, a.daily-list-item, .daily-list-item'));

  // Also let's look at all child nodes or specific structure
  // In the snapshot, we have:
  // link "THU 9/17 82° /70° 49%" followed by description text
  return cards.map(card => {
    // If card is an anchor, the description might be inside or in the next sibling
    const header = card.innerText.trim();
    let desc = '';
    let sibling = card.nextElementSibling;
    if (sibling && !sibling.matches('.daily-list-item, .daily-forecast-card, a.daily-list-item')) {
      desc = sibling.innerText.trim();
    } else {
      // maybe inside card?
      const descEl = card.querySelector('.phrase, .short-date, .cond');
      if (descEl) desc = descEl.innerText.trim();
    }
    return { header, desc };
  });
});
console.log(JSON.stringify(fullDailyData, null, 2));

